import 'package:flutter/material.dart';import 'package:firebase_auth/firebase_auth.dart';import '../../../services/personal_ai/focus_history_service.dart';
class AurenFocusHistoryScreen extends StatelessWidget{const AurenFocusHistoryScreen({super.key});@override Widget build(BuildContext c){final u=FirebaseAuth.instance.currentUser?.uid;if(u==null)return const Scaffold(body:Center(child:Text('يجب تسجيل الدخول')));final s=FocusHistoryService();return Scaffold(appBar:AppBar(title:const Text('Focus History')),body:StreamBuilder(stream:s.watch(u),builder:(c,x){final docs=x.data?.docs??[];final total=docs.fold<int>(0,(a,d)=>a+(d.data()['minutes'] as num? ?? 0).toInt());return ListView(padding:const EdgeInsets.all(16),children:[Card(child:ListTile(title:const Text('إجمالي وقت التركيز'),subtitle:Text('$total دقيقة'),leading:const Icon(Icons.timer))),const SizedBox(height:8),...docs.map((d)=>ListTile(leading:const Icon(Icons.history),title:Text(d.data()['title'] as String? ?? ''),subtitle:Text('${d.data()['minutes']??0} دقيقة')))]);}));}}